import './style.css'
const ART = {"awake": "data:image/png;base64,", "sleeping": "data:image/png;base64,", "logo": "data:image/png;base64,"}

// Browser storage keys match the previous prototype update.
const KEYS = { cards: 'studybara.flashcards.v1', tasks: 'studybara.planner.v1' }
const warnings = { cards: '', tasks: '' }
function loadList(kind, valid) {
  try {
    const data = JSON.parse(localStorage.getItem(KEYS[kind]) || '[]')
    if (!Array.isArray(data)) throw new Error('Invalid data')
    return data.filter(valid)
  } catch {
    warnings[kind] = 'Saved data could not be loaded. Browser storage may be unavailable.'
    return []
  }
}
const flashcards = loadList('cards', x => x && typeof x.question === 'string' && typeof x.answer === 'string')
const tasks = loadList('tasks', x => x && typeof x.id === 'string' && typeof x.title === 'string' && typeof x.done === 'boolean' && typeof x.due === 'string')
function saveList(kind, data) {
  try { localStorage.setItem(KEYS[kind], JSON.stringify(data)); warnings[kind] = '' }
  catch { warnings[kind] = 'Saving failed. Changes will only remain for this visit.' }
  const note = document.querySelector('#storageNote')
  if (note) note.textContent = storageText(kind)
}
function storageText(kind) {
  return warnings[kind] || 'Saved in this browser only. No account or cross-device sync. Clearing browser data removes saved items.'
}
function storageNote(kind) {
  const note = document.createElement('p'); note.id = 'storageNote'; note.className = 'muted'; note.textContent = storageText(kind); mainContent.appendChild(note)
}
const timer = { mode: 'study', studySeconds: 1500, breakMinutes: 5, total: 1500, remaining: 1500, running: false, deadline: 0, message: 'Ready when you are.' }
let currentPage = 'home'
document.querySelector('#app').innerHTML = `
<div class="app"><header class="topbar">
  <a class="brand" href="#home" aria-label="StudyBara home"><img src="${ART.logo}" alt="StudyBara"></a>
  <span class="prototype-label">Your study companion <span class="badge">Prototype</span></span>
</header><nav class="menu" aria-label="Main navigation">
  <button class="menu-btn" data-page="home">Home</button><button class="menu-btn" data-page="pomodoro">Pomodoro</button>
  <button class="menu-btn" data-page="flashcards">Flashcards</button><button class="menu-btn" data-page="quiz">Quiz</button><button class="menu-btn" data-page="planner">Planner</button>
</nav><main class="card" id="mainContent" tabindex="-1"></main>
<footer>StudyBara · Team-designed artwork · Early working prototype</footer></div>`
const mainContent = document.querySelector('#mainContent')
function petMarkup(sleeping = false) {
  return `<figure class="pet"><img class="pet-art" src="${sleeping ? ART.sleeping : ART.awake}" alt="${sleeping ? 'Resting' : 'Awake'} capybara companion"><figcaption>${sleeping ? 'Time to recharge.' : 'Let’s study together.'}</figcaption></figure>`
}
function renderHome() {
  mainContent.innerHTML = `<div class="home-layout"><div class="companion"><p class="speech">Hey! Ready to crack on with some work?</p>${petMarkup()}</div>
  <div class="home-options"><p class="eyebrow">A little focus, a little progress</p><h1>What would you like to start with?</h1>
    <div class="feature-grid"><button class="feature-btn" data-page="pomodoro">Pomodoro timer<small>Focus, then recharge</small></button>
    <button class="feature-btn" data-page="quiz">Quiz<small>Coming later</small></button>
    <button class="feature-btn" data-page="flashcards">Flashcards<small>Create and revise</small></button>
    <button class="feature-btn" data-page="planner">Planner<small>Plan your next step</small></button></div>
    <p class="muted">One small study session at a time.</p></div></div>`
}
function duration() { return timer.mode === 'study' ? timer.studySeconds : timer.breakMinutes * 60 }
function formatTime(seconds) { return `${Math.floor(seconds / 60).toString().padStart(2,'0')}:${(seconds % 60).toString().padStart(2,'0')}` }
function syncTimer() {
  if (!timer.running) return
  timer.remaining = Math.max(0, Math.ceil((timer.deadline - Date.now()) / 1000))
  if (timer.remaining === 0) {
    timer.running = false
    timer.message = timer.mode === 'study' ? 'Study session complete. Take a break when ready.' : 'Break complete. Ready for another study session?'
  }
}
function toggleTimer() {
  syncTimer()
  if (timer.running) { timer.running = false; timer.message = 'Paused.' }
  else {
    if (!timer.remaining) timer.remaining = timer.total
    timer.deadline = Date.now() + timer.remaining * 1000; timer.running = true
    timer.message = timer.mode === 'study' ? 'Study session running.' : 'Break running.'
  }
  updateTimerView()
}
function resetTimer() { timer.running = false; timer.total = duration(); timer.remaining = timer.total; timer.message = 'Timer reset.'; updateTimerView() }
function switchMode() {
  timer.mode = timer.mode === 'study' ? 'break' : 'study'; resetTimer()
  timer.message = 'Mode changed. Press Start when ready.'; renderTimer()
}
function addTime() {
  syncTimer(); timer.remaining += 300; timer.total += 300
  if (timer.running) timer.deadline += 300000
  timer.message = 'Five minutes added.'; updateTimerView()
}
function updateTimerView() {
  document.title = timer.running ? `${formatTime(timer.remaining)} · StudyBara` : 'StudyBara'
  if (currentPage !== 'pomodoro') return
  const clock = document.querySelector('#timerValue'); if (!clock) return
  clock.textContent = formatTime(timer.remaining)
  document.querySelector('#timerMode').textContent = timer.mode === 'study' ? 'Study session' : 'Break'
  document.querySelector('#toggleTimer').textContent = timer.running ? 'Pause' : timer.remaining === 0 ? 'Start again' : 'Start / Resume'
  document.querySelector('#timerStatus').textContent = timer.message
  document.querySelector('#timerRing').style.setProperty('--progress', `${Math.min(1,Math.max(0,(timer.total-timer.remaining)/timer.total))*360}deg`)
}
function renderTimer() {
  syncTimer()
  mainContent.innerHTML = `<div class="section-heading"><div><p class="eyebrow">Make room for focus</p><h1>Pomodoro timer</h1></div><span class="badge">${timer.mode === 'study' ? 'Focus time' : 'Break time'}</span></div>
  <div class="timer-layout"><div class="timer-main"><div class="timer-ring" id="timerRing"><div class="timer-face"><span id="timerMode"></span><span class="timer-value" id="timerValue" role="timer" aria-label="Time remaining"></span><span>One thing at a time</span></div></div>
  <div class="timer-controls"><button class="menu-btn" id="toggleTimer">Start</button><button class="secondary-btn" id="resetTimer">Reset</button></div></div>
  <div class="timer-side"><div class="duration-fields"><label>Study duration<select id="studyDuration" aria-label="Study duration">${[[1500,'25 minutes'],[3000,'50 minutes'],[10,'10 seconds — demo only']].map(([s,label])=>`<option value="${s}" ${s===timer.studySeconds?'selected':''}>${label}</option>`).join('')}</select></label>
  <label>Next break<select id="breakDuration" aria-label="Next break duration">${[5,10,15].map(n=>`<option value="${n}" ${n===timer.breakMinutes?'selected':''}>${n} minutes</option>`).join('')}</select></label></div>
  <div class="timer-controls"><button class="secondary-btn" id="switchMode">${timer.mode==='study'?'Take a break':'Back to study'}</button><button class="secondary-btn" id="addTime">Add 5 minutes</button></div>
  ${petMarkup(timer.mode==='break')}<h2>Your focus</h2><div id="timerTasks"></div></div></div>
  <p id="timerStatus" class="status" role="status"></p><details><summary>How this prototype timer works</summary><p>Study duration changes reset a study session. Break duration applies to the next break, or use Reset during a break. Switching modes resets the current session. Navigation keeps the timer running; refresh resets it. No sound or background alerts. The 10-second option is for testing only.</p></details>`
  document.querySelector('#toggleTimer').onclick=toggleTimer
  document.querySelector('#resetTimer').onclick=resetTimer
  document.querySelector('#switchMode').onclick=switchMode
  document.querySelector('#addTime').onclick=addTime
  document.querySelector('#studyDuration').onchange=e=>{timer.studySeconds=Number(e.target.value);if(timer.mode==='study')resetTimer();else{timer.message='Study duration saved for the next study session.';updateTimerView()}}
  document.querySelector('#breakDuration').onchange=e=>{timer.breakMinutes=Number(e.target.value);timer.message='Break duration saved. Use Reset to apply it to a break in progress.';updateTimerView()}
  const area=document.querySelector('#timerTasks'), pending=tasks.filter(t=>!t.done)
  if (!pending.length) { const p=document.createElement('p');p.textContent='No pending tasks. Add one in Planner before starting.';area.appendChild(p) }
  else { const ul=document.createElement('ul');pending.slice(0,5).forEach(t=>{const li=document.createElement('li');li.textContent=t.title;ul.appendChild(li)});area.appendChild(ul) }
  updateTimerView()
}
function renderFlashcards() {
  mainContent.innerHTML = `
    <h2>Flashcards</h2>
    <p>Add a question and answer, then use your cards to revise.</p>

    <form id="flashcardForm" class="flashcard-form">
      <label for="questionInput">Question</label>
      <input
        id="questionInput"
        type="text"
        placeholder="For example: What does HTML stand for?"
        required
      >

      <label for="answerInput">Answer</label>
      <textarea
        id="answerInput"
        rows="3"
        placeholder="Enter the answer"
        required
      ></textarea>

      <button type="submit" class="menu-btn">Add flashcard</button>
      <p id="formMessage" role="status"></p>
    </form>

    <h3>Your flashcards</h3>
    <div id="flashcardList"></div>
  `

  const form = document.querySelector('#flashcardForm')
  const questionInput = document.querySelector('#questionInput')
  const answerInput = document.querySelector('#answerInput')
  const formMessage = document.querySelector('#formMessage')
  const flashcardList = document.querySelector('#flashcardList')

  // Displays the cards currently in our list.
  function displayFlashcards() {
    flashcardList.replaceChildren()

    if (flashcards.length === 0) {
      const message = document.createElement('p')
      message.textContent = 'You have not added any flashcards yet.'
      flashcardList.appendChild(message)
      return
    }

    flashcards.forEach((flashcard) => {
      const card = document.createElement('article')
      card.className = 'study-card'

      const question = document.createElement('h4')
      question.textContent = flashcard.question

      const answer = document.createElement('p')
      answer.textContent = flashcard.answer
      answer.hidden = true

      const revealButton = document.createElement('button')
      revealButton.type = 'button'
      revealButton.className = 'menu-btn'
      revealButton.textContent = 'Show answer'

      revealButton.addEventListener('click', () => {
        answer.hidden = !answer.hidden

        revealButton.textContent = answer.hidden
          ? 'Show answer'
          : 'Hide answer'
      })

      card.appendChild(question)
      card.appendChild(revealButton)
      card.appendChild(answer)

      flashcardList.appendChild(card)
    })
  }

  // Adds a new card when the form is submitted.
  form.addEventListener('submit', (event) => {
    event.preventDefault()

    const question = questionInput.value.trim()
    const answer = answerInput.value.trim()

    if (question === '' || answer === '') {
      formMessage.textContent = 'Please enter both a question and an answer.'
      return
    }

    flashcards.push({
      question: question,
      answer: answer
    })

    saveList('cards', flashcards)
    form.reset()
    formMessage.textContent = 'Flashcard added.'
    displayFlashcards()
    questionInput.focus()
  })

  displayFlashcards()
}
function todayLocal() {
  const d=new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`
}
function renderPlanner() {
  mainContent.innerHTML=`<p class="eyebrow">Make a little plan</p><h1>Study planner</h1><p>Add a study task, give it an optional due date, and tick it off when done.</p>
  <form id="plannerForm" class="flashcard-form"><label for="taskTitle">Study task</label><input id="taskTitle" maxlength="200" placeholder="For example: Revise database keys" required>
  <label for="taskDue">Due date (optional)</label><input id="taskDue" type="date"><button class="menu-btn" type="submit">Add task</button><p id="plannerMessage" role="status"></p></form>
  <div class="planner-summary" id="plannerSummary" role="status"></div><div id="taskList"></div>`
  storageNote('tasks')
  document.querySelector('#plannerForm').addEventListener('submit',e=>{
    e.preventDefault(); const title=document.querySelector('#taskTitle').value.trim(), due=document.querySelector('#taskDue').value
    if(!title){document.querySelector('#plannerMessage').textContent='Please enter a task, not just spaces.';return}
    const id=globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(36).slice(2)}`
    tasks.push({id,title,due,done:false});saveList('tasks',tasks)
    document.querySelector('#plannerForm').reset();document.querySelector('#plannerMessage').textContent='Task added.'
    displayTasks();document.querySelector('#taskTitle').focus()
  })
  displayTasks()
}
function displayTasks() {
  const list=document.querySelector('#taskList');list.replaceChildren()
  const pending=tasks.filter(t=>!t.done).length
  document.querySelector('#plannerSummary').textContent=`${pending} to do · ${tasks.length-pending} completed`
  if(!tasks.length){const p=document.createElement('p');p.textContent='No tasks yet. Start with one small thing.';list.appendChild(p);return}
  const sorted=[...tasks].sort((a,b)=>Number(a.done)-Number(b.done)||(a.due||'9999').localeCompare(b.due||'9999'))
  sorted.forEach(task=>{
    const row=document.createElement('article');row.className=`task-row${task.done?' completed':''}`
    const label=document.createElement('label');label.className='task-label'
    const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.checked=task.done
    const text=document.createElement('span');text.textContent=task.title
    checkbox.addEventListener('change',()=>{task.done=checkbox.checked;saveList('tasks',tasks);displayTasks()})
    label.appendChild(checkbox);label.appendChild(text)
    const info=document.createElement('div');info.className='task-meta'
    const date=document.createElement('span')
    if(task.due){date.textContent=`Due ${task.due}${!task.done&&task.due<todayLocal()?' · overdue':''}`;if(!task.done&&task.due<todayLocal())date.className='overdue'}
    else date.textContent='No due date'
    const del=document.createElement('button');del.type='button';del.className='secondary-btn';del.textContent='Delete';del.setAttribute('aria-label',`Delete task: ${task.title}`)
    del.addEventListener('click',()=>{if(!window.confirm('Delete this task?'))return;const i=tasks.findIndex(t=>t.id===task.id);if(i!==-1)tasks.splice(i,1);saveList('tasks',tasks);displayTasks()})
    info.appendChild(date);info.appendChild(del);row.appendChild(label);row.appendChild(info);list.appendChild(row)
  })
}
function navigate(page,focus=false) {
  syncTimer();currentPage=page
  document.querySelectorAll('.menu [data-page]').forEach(b=>{if(b.dataset.page===page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')})
  if(page==='home')renderHome()
  else if(page==='pomodoro')renderTimer()
  else if(page==='flashcards'){renderFlashcards();storageNote('cards')}
  else if(page==='planner')renderPlanner()
  else mainContent.innerHTML='<p class="eyebrow">Still growing</p><h1>Quiz</h1><p>Quizzes are planned for a later version and are not implemented in this prototype.</p><button class="secondary-btn" data-page="home">Back to home</button>'
  updateTimerView();if(focus)mainContent.focus()
}
document.querySelector('#app').addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b)navigate(b.dataset.page,true)})
document.querySelector('.brand').onclick=e=>{e.preventDefault();navigate('home',true)}
setInterval(()=>{syncTimer();updateTimerView()},250)
document.addEventListener('visibilitychange',()=>{syncTimer();updateTimerView()})
navigate('home')
